{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "あぁどうしようもないほどに",
        "私に蠢く獣",
        "水面浮かんで浮かんでは消えるあぶく"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "あぁどうしようもなく悲しい",
        "私を動かす獣",
        "トートロジー握った手のあぶく"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "過ぎ去る雲を思うより",
        "遥かへ遠吠え",
        "息継ぐ暇もないほど",
        "苦しいあれで"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "悠々悠々夢を焼け",
        "魂の白い白い色で",
        "喜びの火に火をつけたいだけ",
        "想像は少しの泡銭",
        "冷めない言葉の両手で",
        "燃え尽きないものを数えて",
        "掬いたいだけ"
      ]
    }
  ],
  "section": "V1",
  "phrases": [
    {
      "id": "V1-01",
      "ja": "あぁどうしようもないほどに",
      "budget": {
        "min": 8,
