      },
      "pattern": [
        1,
        4,
        3
      ]
    },
    {
      "id": "V1-02",
      "ja": "私に蠢く獣",
      "budget": {
        "min": 8,
        "max": 8
      },
      "pattern": [
        3,
        5
      ]
    },
    {
      "id": "V1-03",
      "ja": "水面浮かんで浮かんでは消えるあぶく",
      "budget": {
        "min": 15,
        "max": 15
      },
      "pattern": [
        2,
        6,
        4,
        3
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "闷 胸口有火 烧不透"
        },
        {
          "id": "V1-02",
          "zh": "骨头里 有兽在蠕动"
        },
        {
          "id": "V1-03",
          "zh": "水面 泡沫浮起又破 破了又生 碎无声"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "啊，无可奈何地"
        },
        {
          "id": "V1-02",
          "zh": "我心中躁动的兽"
        },
        {
          "id": "V1-03",
          "zh": "水面浮现又破灭的泡沫"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "啊，无可奈何般"
        },
        {
          "id": "V1-02",
          "zh": "我体内蠢动的兽"
        },
        {
          "id": "V1-03",
          "zh": "水面浮现又浮现即消失的泡沫"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "啊 无可奈何的心底"
        },
        {
          "id": "V1-02",
          "zh": "沉睡的兽在低语"
        },
        {
          "id": "V1-03",
          "zh": "水面浮起又沉入 消散的泡影"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "啊 按不住的 在翻涌"
        },
        {
          "id": "V1-02",
          "zh": "胸腔里 蠢动的野兽"
        },
        {
          "id": "V1-03",
          "zh": "水面 鼓起来又破掉 没有声音 又一颗"
        }
      ]
    }
  ]
}

